import{_ as a,o as i,c as e,ae as r}from"./chunks/framework.B6gjLfeO.js";const u=JSON.parse('{"title":"Privacy Policy（隐私政策）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy-policy.md","filePath":"guide/privacy-policy.md","lastUpdated":1775036159000}'),o={name:"guide/privacy-policy.md"};function t(h,l,n,d,c,p){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="privacy-policy-隐私政策" tabindex="-1">Privacy Policy（隐私政策） <a class="header-anchor" href="#privacy-policy-隐私政策" aria-label="Permalink to &quot;Privacy Policy（隐私政策）&quot;">​</a></h1><p>最后更新日期：2026-03-31   生效日期：2017-01-01</p><p>欢迎使用 <strong>姬长信 API For Docker</strong>（以下简称“本服务”或“本平台”）。本隐私政策用于说明本平台在你访问、调用、集成或使用本服务时，如何收集、使用、存储、共享和保护相关信息。</p><p>请在使用本服务前仔细阅读本隐私政策。你一旦使用本服务，即表示你已理解并同意本隐私政策所述内容。</p><h2 id="_1-我们收集的信息" tabindex="-1">1. 我们收集的信息 <a class="header-anchor" href="#_1-我们收集的信息" aria-label="Permalink to &quot;1. 我们收集的信息&quot;">​</a></h2><p>为保障本服务的正常运行、安全维护、性能分析及违规审查，本平台可能收集和处理以下信息：</p><h3 id="_1-1-你主动提供的信息" tabindex="-1">1.1 你主动提供的信息 <a class="header-anchor" href="#_1-1-你主动提供的信息" aria-label="Permalink to &quot;1.1 你主动提供的信息&quot;">​</a></h3><p>当你通过邮件或其他方式联系本平台时，你可能主动提供以下信息：</p><ul><li>邮箱地址；</li><li>联系内容；</li><li>问题描述、反馈内容；</li><li>你主动提供的其他信息。</li></ul><h3 id="_1-2-在你使用服务过程中自动收集的信息" tabindex="-1">1.2 在你使用服务过程中自动收集的信息 <a class="header-anchor" href="#_1-2-在你使用服务过程中自动收集的信息" aria-label="Permalink to &quot;1.2 在你使用服务过程中自动收集的信息&quot;">​</a></h3><p>当你访问或调用本服务时，本平台可能自动记录以下技术信息或日志信息：</p><ul><li>来源域名；</li><li>访问 IP 地址；</li><li>调用时间；</li><li>请求路径；</li><li>请求方法；</li><li>请求频率；</li><li>调用次数；</li><li>流量消耗；</li><li>User-Agent、Referer、基础设备或浏览器特征；</li><li>响应状态码；</li><li>错误日志、安全日志、风控日志；</li><li>为保障系统稳定所必需的其他技术信息。</li></ul><h3 id="_1-3-特别说明" tabindex="-1">1.3 特别说明 <a class="header-anchor" href="#_1-3-特别说明" aria-label="Permalink to &quot;1.3 特别说明&quot;">​</a></h3><p>根据本平台当前服务规则，本平台会记录你的<strong>域名、使用流量、调用次数等信息，并存储六个月</strong>。如果你对此介意，请停止使用本服务。</p><h2 id="_2-我们如何使用这些信息" tabindex="-1">2. 我们如何使用这些信息 <a class="header-anchor" href="#_2-我们如何使用这些信息" aria-label="Permalink to &quot;2. 我们如何使用这些信息&quot;">​</a></h2><p>我们收集和使用上述信息，通常用于以下目的：</p><ol><li>提供、维护和优化本服务；</li><li>统计接口使用情况、系统负载和服务质量；</li><li>识别异常流量、滥用行为、攻击行为和安全风险；</li><li>实施限流、鉴权、封禁、加白或其他访问控制策略；</li><li>处理用户反馈、申诉、技术支持和投诉举报；</li><li>履行法律法规要求、监管义务或配合司法/行政机关要求；</li><li>保护本平台、其他用户及第三方的合法权益；</li><li>用于与本服务直接相关的其他合理用途。</li></ol><h2 id="_3-处理信息的法律基础" tabindex="-1">3. 处理信息的法律基础 <a class="header-anchor" href="#_3-处理信息的法律基础" aria-label="Permalink to &quot;3. 处理信息的法律基础&quot;">​</a></h2><p>在适用法律要求下，我们处理相关信息的法律基础可能包括：</p><ul><li>为提供你请求的服务所必需；</li><li>为保障平台安全、稳定和正常运营所必需；</li><li>为履行法律义务所必需；</li><li>基于你作出的同意；</li><li>基于本平台的合法利益，且该等利益不与用户的基本权利和自由相冲突。</li></ul><h2 id="_4-信息保存期限" tabindex="-1">4. 信息保存期限 <a class="header-anchor" href="#_4-信息保存期限" aria-label="Permalink to &quot;4. 信息保存期限&quot;">​</a></h2><ol><li>本平台对于来源域名、流量、调用次数及相关使用日志，通常保存 <strong>六个月</strong>。</li><li>对于为安全审计、违规调查、争议处理、法律合规所必需的信息，本平台可能在合理必要范围内延长保存期限。</li><li>保存期限届满后，本平台将根据技术条件、业务需要和法律要求，对相关信息进行删除、匿名化处理或采取其他适当处理方式。</li></ol><h2 id="_5-信息共享、转让与披露" tabindex="-1">5. 信息共享、转让与披露 <a class="header-anchor" href="#_5-信息共享、转让与披露" aria-label="Permalink to &quot;5. 信息共享、转让与披露&quot;">​</a></h2><h3 id="_5-1-共享" tabindex="-1">5.1 共享 <a class="header-anchor" href="#_5-1-共享" aria-label="Permalink to &quot;5.1 共享&quot;">​</a></h3><p>本平台原则上不会向无关第三方出售你的个人信息。   但在以下情形中，本平台可能在必要范围内共享相关信息：</p><ol><li>与提供基础设施、存储、CDN、安全防护、日志分析、监控支持的服务供应商共享；</li><li>为履行法律法规义务、响应司法机关、行政机关或监管部门要求而共享；</li><li>为保护本平台、用户或公众的合法权益、安全和财产而有必要共享；</li><li>你自行授权或同意的其他情形。</li></ol><h3 id="_5-2-转让" tabindex="-1">5.2 转让 <a class="header-anchor" href="#_5-2-转让" aria-label="Permalink to &quot;5.2 转让&quot;">​</a></h3><p>除非发生合并、分立、资产出售、重组或其他类似交易，且会依法处理相关信息，否则本平台不会随意转让你的个人信息。</p><h3 id="_5-3-公开披露" tabindex="-1">5.3 公开披露 <a class="header-anchor" href="#_5-3-公开披露" aria-label="Permalink to &quot;5.3 公开披露&quot;">​</a></h3><p>本平台仅会在以下情况下公开披露你的信息：</p><ul><li>获得你的明确同意；</li><li>法律法规、行政命令、司法裁判或监管要求明确要求；</li><li>为维护重大公共利益或重大合法权益所必需。</li></ul><h2 id="_6-cookie-与类似技术" tabindex="-1">6. Cookie 与类似技术 <a class="header-anchor" href="#_6-cookie-与类似技术" aria-label="Permalink to &quot;6. Cookie 与类似技术&quot;">​</a></h2><p>如果本平台站点使用 Cookie、本地存储或类似技术，其用途通常包括：</p><ul><li>维持基础访问功能；</li><li>分析站点流量与性能；</li><li>改善用户体验；</li><li>提升安全性与风控能力。</li></ul><p>你可通过浏览器设置限制部分 Cookie，但这可能影响某些功能正常使用。</p><h2 id="_7-数据安全" tabindex="-1">7. 数据安全 <a class="header-anchor" href="#_7-数据安全" aria-label="Permalink to &quot;7. 数据安全&quot;">​</a></h2><p>本平台会采取合理的技术和管理措施保护收集到的信息，包括但不限于：</p><ul><li>访问控制；</li><li>日志审计；</li><li>异常监测；</li><li>传输安全；</li><li>存储安全；</li><li>最小必要权限控制。</li></ul><p>但请理解，互联网环境并非绝对安全，本平台无法保证任何信息在传输或存储过程中绝对安全。你应自行采取适当安全措施保护你的系统、密钥、接口调用环境及业务数据。</p><h2 id="_8-第三方服务与第三方数据来源" tabindex="-1">8. 第三方服务与第三方数据来源 <a class="header-anchor" href="#_8-第三方服务与第三方数据来源" aria-label="Permalink to &quot;8. 第三方服务与第三方数据来源&quot;">​</a></h2><ol><li>本平台部分接口内容可能来自第三方平台、公开数据源或合作来源。</li><li>你在使用相关接口时，还可能受到第三方平台政策、授权条件或数据规则的约束。</li><li>本平台对第三方服务的可用性、准确性、时效性或其隐私保护措施不作独立保证。</li></ol><h2 id="_9-未成年人保护" tabindex="-1">9. 未成年人保护 <a class="header-anchor" href="#_9-未成年人保护" aria-label="Permalink to &quot;9. 未成年人保护&quot;">​</a></h2><p>若你属于未成年人，应在监护人同意和指导下使用本服务。   如发现未成年人在不符合适用法律要求的情况下提供了相关信息，请及时联系我们处理。</p><h2 id="_10-你的权利" tabindex="-1">10. 你的权利 <a class="header-anchor" href="#_10-你的权利" aria-label="Permalink to &quot;10. 你的权利&quot;">​</a></h2><p>在适用法律允许的范围内，你可能享有以下权利：</p><ul><li>知悉我们是否处理你的相关信息；</li><li>访问、复制、更正你主动提供的信息；</li><li>请求删除部分信息；</li><li>请求限制处理；</li><li>撤回同意（如处理基于同意）；</li><li>进行投诉或申诉。</li></ul><p>鉴于本平台主要处理的是接口访问日志、来源域名、流量与调用统计等技术信息，部分请求可能受限于法律义务、安全审计需求、技术可行性或平台合理运营需要。本平台将在合理范围内进行处理。</p><h2 id="_11-跨境传输" tabindex="-1">11. 跨境传输 <a class="header-anchor" href="#_11-跨境传输" aria-label="Permalink to &quot;11. 跨境传输&quot;">​</a></h2><p>如果因使用的基础设施、CDN、云服务、安全防护或技术架构需要，相关数据可能在不同地区进行传输、处理或存储。本平台会在合理可行范围内采取适当保护措施。</p><h2 id="_12-隐私政策更新" tabindex="-1">12. 隐私政策更新 <a class="header-anchor" href="#_12-隐私政策更新" aria-label="Permalink to &quot;12. 隐私政策更新&quot;">​</a></h2><p>本平台有权根据业务变化、法律法规要求或运营需要更新本隐私政策。   更新后的版本一经发布即生效。你在更新后继续使用本服务的，视为你接受更新后的隐私政策。</p><h2 id="_13-联系我们" tabindex="-1">13. 联系我们 <a class="header-anchor" href="#_13-联系我们" aria-label="Permalink to &quot;13. 联系我们&quot;">​</a></h2><p>如你对本隐私政策有任何疑问、意见、投诉或数据处理请求，可通过以下方式联系：</p><ul><li>邮箱：<code>admin@isoyu.com</code></li></ul><h2 id="_14-说明" tabindex="-1">14. 说明 <a class="header-anchor" href="#_14-说明" aria-label="Permalink to &quot;14. 说明&quot;">​</a></h2><p>本隐私政策应与《Terms of Service（服务条款）》一并阅读。若两者存在不一致之处，以具体条款适用场景为准。</p>',56)])])}const _=a(o,[["render",t]]);export{u as __pageData,_ as default};
